(6601718, 984868, 80896, '<td valign="top">Perfect composition, excellent colours and detail.</td>', 'Perfect composition, excellent colours and detail.', '2011-11-23 07:59:06.000000', NULL, 1),
(6601737, 984959, 54446, '<td valign="top">Good "pop" of colors.  And, you''ve brought up the detail in the shadows.</td>', 'Good "pop" of colors.  And, you''ve brought up the detail in the shadows.', '2011-11-23 08:31:05.000000', NULL, 1),
(6601741, 984656, 54446, '<td valign="top">I admire the HDR processing in this image very much.  Excellent detail in the interior shadows, yet perfect exposure in the white clouds (sun reflectors).  You''ve managed to keep the colors natural looking.  Also, it''s an interesting subject... well composed.</td>', 'I admire the HDR processing in this image very much.  Excellent detail in the interior shadows, yet perfect exposure in the white clouds (sun reflectors).  You''ve managed to keep the colors natural looking.  Also, it''s an interesting subject... well composed.', '2011-11-23 08:31:59.000000', NULL, 1),
(6601746, 984868, 137762, '<td valign="top">Great use of HDR! I have the feeling the HDR actually contributes to the message you want to convey instead of it being a fancy trick to make a picture more interesting. Well done!</td>', 'Great use of HDR! I have the feeling the HDR actually contributes to the message you want to convey instead of it being a fancy trick to make a picture more interesting. Well done!', '2011-11-23 08:42:58.000000', NULL, 1),
