(6686086, 984743, 129512, '<td valign="top">Prints??</td>', 'Prints??', '2012-02-21 12:20:11.000000', NULL, 0),
(6721011, 984868, 146356, '<td valign="top">Very nice picture.I can''t imagine the time the individual leaves might have took.<br/> <br/>I find it cleaner to make HDRs of jpegs. I notice you mentioned you HDR''ed the three raws directly and this looks better than what i can muster. Do you think this could come from the difference in programs (Photomatix vs HDR Efex Pro) or is there a secret sauce i m missing?</td>', 'Very nice picture.I can''t imagine the time the individual leaves might have took. I find it cleaner to make HDRs of jpegs. I notice you mentioned you HDR''ed the three raws directly and this looks better than what i can muster. Do you think this could come from the difference in programs (Photomatix vs HDR Efex Pro) or is there a secret sauce i m missing?', '2012-03-23 10:54:14.000000', NULL, 0),
(6721074, 984868, 114969, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Devinder:</b></div><hr/><i>I notice you mentioned you HDR''ed the three raws directly and this looks better than what i can muster. Do you think this could come from the difference in programs (Photomatix vs HDR Efex Pro) or is there a secret sauce i m missing? </i></td></tr></table> <br/> <br/>Thank you for your comment. I don''t think the tool you use is that important at all, I''m quite confident saying Photomatix could have been used there (as long as one knows it well enough). Moreover, to my knowledge, these tools do not work directly on RAWs anyway, at best they import 16 bits images out of them and start to work from there (TIFF usually). What is important to know about the processing of that particular image, is the fact the tonemapped HDR resulting image was merely the beginning, not the final result in any case. I simply used the HDR plugin to obtain crispy texture and details on the trunk and foreground, but there are like 30 other processing layers above it, in order to reach this result. In fact, I just used the HDR tool to enhance the dynamic range of my camera, not at all to create some kind of special effect, that was not my point.</td>', 'Originally posted by Devinder:I notice you mentioned you HDR''ed the three raws directly and this looks better than what i can muster. Do you think this could come from the difference in programs (Photomatix vs HDR Efex Pro) or is there a secret sauce i m missing?   Thank you for your comment. I don''t think the tool you use is that important at all, I''m quite confident saying Photomatix could have been used there (as long as one knows it well enough). Moreover, to my knowledge, these tools do not work directly on RAWs anyway, at best they import 16 bits images out of them and start to work from there (TIFF usually). What is important to know about the processing of that particular image, is the fact the tonemapped HDR resulting image was merely the beginning, not the final result in any case. I simply used the HDR plugin to obtain crispy texture and details on the trunk and foreground, but there are like 30 other processing layers above it, in order to reach this result. In fact, I just used the HDR tool to enhance the dynamic range of my camera, not at all to create some kind of special effect, that was not my point.', '2012-03-23 11:57:57.000000', NULL, 0),
(6724273, 984868, 146356, '<td valign="top">Thanks for the reply, I get that its a starting step. My specific issue is with noise. Even at 100 ISO, i end up introducing more noise with my raw stuff for some reason. i got to look into it i suppose - thanks for the input!</td>', 'Thanks for the reply, I get that its a starting step. My specific issue is with noise. Even at 100 ISO, i end up introducing more noise with my raw stuff for some reason. i got to look into it i suppose - thanks for the input!', '2012-03-27 17:29:43.000000', NULL, 0),
(6764709, 984872, 32345, '<td valign="top">Wow! Great details!</td>', 'Wow! Great details!', '2012-05-09 13:34:53.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6966326, 984858, 54446, '<td valign="top">I gave this a "5".  I like the tree.  However, as I mentioned more than a year ago, the sky through the branches is highly unnatural.  By that, I mean there are areas of gray sky next to clear sky.  This is not a desirable outcome of HDR blending.  HDR applications, like Photomatix, do not handle the high contrast transitions between bright tones and dark tones.  I strongly recommend HDR Efex Pro 2 from NikSoftware.  For an image like this, you''ll produce much more desirable results.</td>', 'I gave this a "5".  I like the tree.  However, as I mentioned more than a year ago, the sky through the branches is highly unnatural.  By that, I mean there are areas of gray sky next to clear sky.  This is not a desirable outcome of HDR blending.  HDR applications, like Photomatix, do not handle the high contrast transitions between bright tones and dark tones.  I strongly recommend HDR Efex Pro 2 from NikSoftware.  For an image like this, you''ll produce much more desirable results.', '2013-01-29 12:58:14.000000', NULL, 0),
(7024235, 984685, 136989, '<td valign="top">Ooh I want to reach out and pet the pretty pony.  Terrific details all around and such depth to the golden hues of the pony.  I really love your pics. :)</td>', 'Ooh I want to reach out and pet the pretty pony.  Terrific details all around and such depth to the golden hues of the pony.  I really love your pics. :)', '2013-04-21 16:55:18.000000', NULL, 0),
(7243787, 984344, 54446, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by hopefulcrafty1:</b></div><hr/><i> I like the way you can see the details in both the light and dark areas like you should in an HDR photograph.  However, I would like to see more of a clear subject matter.  This would help to seperate the shot from appearing like a snapshot of the woods. </i></td></tr></table> <br/>With all due respect, this is a carefully chosen and precisely composed landscape scene.  It is hardly a snapshot.</td>', 'Originally posted by hopefulcrafty1: I like the way you can see the details in both the light and dark areas like you should in an HDR photograph.  However, I would like to see more of a clear subject matter.  This would help to seperate the shot from appearing like a snapshot of the woods.  With all due respect, this is a carefully chosen and precisely composed landscape scene.  It is hardly a snapshot.', '2014-07-24 12:02:02.000000', NULL, 0),
(7597638, 984944, 117099, '<td valign="top">Lovely!</td>', 'Lovely!', '2018-09-25 19:55:04.000000', NULL, 0);
